            return [];
        }
        $className = $scope->resolveName($node->class);
        if ((new QualifiedName($className))->isBuiltinType()) {
            return [];
        }

        return [new InstantiationEdge($source, new ClassNode(ClassNodeId::of($className), false, null), $meta)];
    }

